package com.fazecast.jSerialComm; import java.io.*; public class SerialPort { public static final int ONE_STOP_BIT=1, NO_PARITY=0, TIMEOUT_READ_BLOCKING=1; public static SerialPort[] getCommPorts(){return new SerialPort[0];} public static SerialPort getCommPort(String n){return new SerialPort(n);} private final String name; public SerialPort(){this("COM");} public SerialPort(String n){name=n;} public String getSystemPortName(){return name;} public void setComPortParameters(int a,int b,int c,int d){} public void setComPortTimeouts(int a,int b,int c){} public boolean openPort(){return true;} public boolean closePort(){return true;} public boolean isOpen(){return true;} public InputStream getInputStream(){return new ByteArrayInputStream(new byte[0]);} public OutputStream getOutputStream(){return new ByteArrayOutputStream();} }
